    """AES/CBC/PKCS5Padding with a zero IV; returns base64 ciphertext."""
    from cryptography.hazmat.primitives import padding
    from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
    padder = padding.PKCS7(128).padder()
    data = padder.update(plaintext.encode("utf-8")) + padder.finalize()
    enc = Cipher(algorithms.AES(key_raw), modes.CBC(b"\x00" * 16)).encryptor()
    return base64.b64encode(enc.update(data) + enc.finalize()).decode()


def _aes_decrypt(key_raw, b64_content):
    from cryptography.hazmat.primitives import padding
    from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
    dec = Cipher(algorithms.AES(key_raw), modes.CBC(b"\x00" * 16)).decryptor()
    data = dec.update(base64.b64decode(b64_content)) + dec.finalize()
    unpadder = padding.PKCS7(128).unpadder()
    plain = unpadder.update(data) + unpadder.finalize()
    try:
        return plain.decode("utf-8")
    except UnicodeDecodeError:
        # The gateway encodes response content in GBK (its default charset).
        return plain.decode("gbk")


def is_configured():
    return bool(os.environ.get("ALIPAY_APP_ID")) and bool(
        os.environ.get("ALIPAY_APP_PRIVATE_KEY")
    ) and bool(os.environ.get("ALIPAY_PUBLIC_KEY"))


def _wrap_pem(body, label):
    if "-----BEGIN" in body:
        return body
    body = "".join(body.split())
    lines = [body[i:i + 64] for i in range(0, len(body), 64)]
    return f"-----BEGIN {label}-----\n" + "\n".join(lines) + f"\n-----END {label}-----"


def _load_private_key(text):
    from cryptography.hazmat.primitives import serialization
    pem = _wrap_pem(text, "PRIVATE KEY")
    try:
        return serialization.load_pem_private_key(pem.encode(), password=[[REDACTED:PASSWORD]]
    except ValueError:
        pem = _wrap_pem(text, "RSA PRIVATE KEY")
        return serialization.load_pem_private_key(pem.encode(), password=[[REDACTED:PASSWORD]]


def _load_public_key(text):
    from cryptography.hazmat.primitives import serialization
    return serialization.load_pem_public_key(
        _wrap_pem(text, "PUBLIC KEY").encode()
    )


def _sign_params(params):
    """RSA2 (SHA256withRSA) signature over the sorted k=v query string.

    Per the current OpenAPI spec, only `sign` is excluded from the signed
    content — `sign_type` itself IS part of it (the old mapi-era rule of
    excluding both no longer applies to gateway.do requests).
    """
    content = "&".join(
        f"{k}={params[k]}" for k in sorted(params) if k != "sign"
    )
    from cryptography.hazmat.primitives import hashes
    from cryptography.hazmat.primitives.asymmetric import padding
    key = _load_private_key(os.environ["ALIPAY_APP_PRIVATE_KEY"])
    signature = key.sign(
        content.encode("utf-8"), padding.PKCS1v15(), hashes.SHA256()
    )
    return base64.b64encode(signature).decode()


def _verify_params(params, signature):
    content = "&".join(
        f"{k}={params[k]}" for k in sorted(params) if k != "sign"
    )
    from cryptography.hazmat.primitives import hashes
    from cryptography.hazmat.primitives.asymmetric import padding
    key = _load_public_key(os.environ["ALIPAY_PUBLIC_KEY"])
    try:
        key.verify(
            base64.b64decode(signature),
            content.encode("utf-8"),
            padding.PKCS1v15(),
            hashes.SHA256(),
        )
        return True
    except Exception:
        return False


def precreate(subject, out_trade_no, total_amount, notify_url):
    """Create a face-to-face order. Returns (qr_code, error_message)."""
    if not is_configured():
        return None, "在线支付未配置"
    biz = json.dumps(
        {
            "out_trade_no": out_trade_no,
            "total_amount": total_amount,
            "subject": subject,
            "timeout_express": "30m",
        },
        ensure_ascii=False,
    )
    params = {
        "app_id": os.environ["ALIPAY_APP_ID"],
        "method": "alipay.trade.precreate",
        "format": "JSON",
        "charset": "utf-8",
        "sign_type": "RSA2",
        "timestamp": datetime.now(timezone(timedelta(hours=8))).strftime(
            "%Y-%m-%d %H:%M:%S"
        ),
        "version": "1.0",
        "notify_url": notify_url,
        "biz_content": biz,
    }
    # Content encryption (接口内容加密): encrypt biz_content with the AES
    # key and mark the request; the signature covers the encrypted value.
    aes_raw = _aes_raw_key()
    if aes_raw:
        params["biz_content"] = _aes_encrypt(aes_raw, biz)
        params["encrypt_type"] = "AES"
    params["sign"] = _sign_params(params)
    body = urllib.parse.urlencode(params).encode()
    req = urllib.request.Request(GATEWAY, data=body, method="POST")
    try:
        with urllib.request.urlopen(req, timeout=15) as resp:
            raw = resp.read()
            ctype = resp.headers.get("Content-Type", "")
    except Exception as exc:
        return None, f"支付网关请求失败: {exc}"
    # The gateway replies in GBK by default even when we request utf-8.
    charset = "utf-8"
    if "charset=" in ctype:
        charset = ctype.split("charset=")[-1].split(";")[0].strip().lower()
    try:
        result = json.loads(raw.decode(charset, errors="replace"))
    except Exception:
        result = json.loads(raw.decode("utf-8", errors="replace"))
    payload = result.get("alipay_trade_precreate_response", {})
    if isinstance(payload, str) and aes_raw:
        # Encrypted mode: the response node value is an encrypted string.
        try:
            payload = json.loads(_aes_decrypt(aes_raw, payload))
        except Exception as exc:
            return None, f"响应解密失败: {exc}"
    if payload.get("code") != "10000":
        return None, f"下单失败: {payload.get('sub_msg') or payload.get('msg')}"
    return payload.get("qr_code"), None


def build_page_pay_url(out_trade_no, total_amount, subject, notify_url, return_url):
    """Build the alipay.trade.page.pay redirect URL (PC web payment).

    Constructed entirely offline — no gateway call — so it works from any
    server. The customer's browser opens the URL and pays on Alipay's
    hosted page; the result arrives via notify_url (POST) and return_url.
    """
    app_id = os.environ["ALIPAY_APP_ID"]
    aes_raw = _aes_raw_key()
    biz = json.dumps({
        "out_trade_no": out_trade_no,
        # Empirical 2026-10-31: FAST_INSTANT_TRADE_PAY_PAGE gets every trade
        # rejected with INVALID_PARAMETER (订单信息无法识别) on both our apps;
        # FAST_INSTANT_TRADE_PAY — the value Alipay's own debug console fills —
        # passes trade creation.
        "product_code": "FAST_INSTANT_TRADE_PAY",
        "total_amount": total_amount,
        "subject": subject,
    }, ensure_ascii=False)
    params = {
        "app_id": app_id,
        "method": "alipay.trade.page.pay",
        "format": "JSON",
        "charset": "utf-8",
        "sign_type": "RSA2",
        "timestamp": datetime.now(timezone(timedelta(hours=8))).strftime(
            "%Y-%m-%d %H:%M:%S"
        ),
        "version": "1.0",
        "notify_url": notify_url,
        "return_url": return_url,
        "biz_content": biz,
    }
    if aes_raw:
        params["biz_content"] = _aes_encrypt(aes_raw, biz)
        params["encrypt_type"] = "AES"
    params["sign"] = _sign_params(params)
    return GATEWAY + "?" + urllib.parse.urlencode(params)


def build_transfer_link(user_id, amount, note):
    """Personal-account transfer deep link with prefilled amount and remark.

    Opens the payer's Alipay app on the transfer page with recipient, amount
    and remark already filled — the payer only confirms. The remark carries
    the order id, so arriving payments match orders without cent-suffix
    tricks. Uses the personal account UID (2088…) as recipient.
    """
    qs = urllib.parse.urlencode({
        "appId": "20000123",
        "actionType": "toAccount",
        "userId": user_id,
        "money": amount,
        "note": note,
    })
    return "alipays://platformapi/startapp?" + qs


def verify_notify(form):
    """Validate an async notify POST. Returns (ok, dict_with_details)."""
    if not is_configured():
        return False, {"reason": "not_configured"}
    data = {k: v for k, v in form.items()}
    signature = data.pop("sign", None)
    if not signature or not _verify_params(data, signature):
        return False, {"reason": "bad_signature"}
    if data.get("app_id") != os.environ["ALIPAY_APP_ID"]:
        return False, {"reason": "app_id_mismatch"}
    return True, {
        "out_trade_no": data.get("out_trade_no"),
        "trade_no": data.get("trade_no"),
        "trade_status": data.get("trade_status"),
        "total_amount": data.get("total_amount"),
    }

