"""DocKit — 文档优化工具 SaaS. Flask entry point with all routes."""
import hmac
import os
import re
import secrets
import threading
import time
from concurrent.futures import ThreadPoolExecutor
from concurrent.futures import TimeoutError as FuturesTimeoutError
from datetime import datetime, timezone

from flask import (
    Flask, abort, flash, redirect, render_template, request, send_file,
    send_from_directory, session, url_for,
)
from werkzeug.middleware.proxy_fix import ProxyFix
from werkzeug.utils import secure_filename

import auth
import alipay
import db
from admin import admin_bp
from processor import ALLOWED_EXTENSIONS, process_document

BASE_DIR = os.path.dirname(os.path.abspath(__file__))
COLLECTED_DIR = os.path.join(BASE_DIR, "collected")
UNLIMITED_MONTHLY_LIMIT = 30

db.load_env()

app = Flask(__name__)
app.config["SECRET_KEY"] = os.environ.get("SECRET_KEY") or secrets.token_hex(32)
app.config["MAX_CONTENT_LENGTH"] = 25 * 1024 * 1024  # matches nginx 25m
app.config["COLLECTED_DIR"] = COLLECTED_DIR
app.config["SESSION_COOKIE_HTTPONLY"] = True
app.config["SESSION_COOKIE_SAMESITE"] = "Lax"
# Trust the single nginx in front of us (X-Forwarded-For / -Proto) so the
# per-IP rate limiter sees real client IPs. Keep :5000 firewalled from the
# internet — direct access bypasses this header.
app.wsgi_app = ProxyFix(app.wsgi_app, x_for=1, x_proto=1)
app.register_blueprint(admin_bp)
app.jinja_env.globals["yuan"] = db.yuan
app.jinja_env.globals["alipay_ready"] = alipay.is_configured

# Bounded core execution: at most 2 concurrent jobs, each capped at 120s.
# A hung or pathological file then fails instead of pinning the 1C2G box.
# Note: on timeout the worker thread itself cannot be killed; the slot is
# freed so the service stays responsive, the stuck thread ends on its own.
CORE_POOL = ThreadPoolExecutor(max_workers=2, thread_name_prefix="core")
CORE_SLOTS = threading.BoundedSemaphore(2)
CORE_TIMEOUT_SECONDS = 120
CORE_QUEUE_WAIT_SECONDS = 60

# Stop accepting new jobs once stored output exceeds this, so the disk
# filling up cannot take the whole service down.
STORAGE_CAP_BYTES = int(os.environ.get("DOCKIT_STORAGE_CAP_MB", "5120")) * 1024 * 1024
# Alipay hosted-page payment (电脑网站支付) switch. Keep off until the
# open-platform side is confirmed able to actually collect (personal
# accounts are restricted); when off, orders are paid via the personal
# QR + listener/manual confirmation.
PAGE_PAY_ENABLED = os.environ.get("ALIPAY_PAGE_PAY", "off").lower() in ("1", "on", "true")
# Personal-account transfer deep links (预填金额+备注的个人转账). When set to
# the merchant's 2088 UID, the pay page offers a transfer QR whose amount and
# remark (order id) are prefilled — payment matching then works by remark,
# with no cent-suffix needed.
TRANSFER_USER_ID = os.environ.get("TRANSFER_ALIPAY_USER_ID", "")
_storage_cache = {"ts": 0.0, "bytes": 0}

_FILENAME_RE = re.compile(r"^[\w\u4e00-\u9fff.\- ]{1,120}$")


class CoreBusy(Exception):
    pass


class CoreTimeout(Exception):
    pass


# ---------------------------------------------------------------- helpers

def ts_dir_name():
    """Collision-free directory name for one processing job."""
    now = datetime.now(timezone.utc)
    return f"{now:%Y%m%d-%H%M%S}-{now.microsecond // 1000:03d}-{secrets.token_hex(3)}"


def file_extension(filename):
    return os.path.splitext(filename)[1].lower()


def _magic_ok(stream, ext):
    """Content sniff: extension must match the file's magic bytes."""
    head = stream.read(8)
    stream.seek(0)
    if not head:
        return False
    if ext == ".pdf":
        return head.startswith(b"%PDF-")
    if ext == ".png":
        return head.startswith(b"\x89PNG")
    if ext in (".jpg", ".jpeg"):
        return head.startswith(b"\xff\xd8\xff")
    return head.startswith(b"PK\x03\x04")  # docx/xlsx are zip containers


def validate_upload(file):
    """Returns (original_name, error_message)."""
    if not file or not file.filename:
        return None, "请选择要处理的文件"
    original = secure_filename(file.filename) or file.filename
    if not _FILENAME_RE.match(original):
        return None, "文件名包含不支持的字符"
    ext = file_extension(original)
    if ext not in ALLOWED_EXTENSIONS:
        return None, "不支持的文件类型（支持 pdf / docx / xlsx / png / jpg）"
    if not _magic_ok(file.stream, ext):
        return None, "文件内容与扩展名不符，或文件为空"
    return original, None


def storage_usage():
    """Total bytes under collected/, cached for 60s. Over-cap readings are
    never cached, so the service recovers as soon as space is freed."""
    now = time.time()
    stale = now - _storage_cache["ts"] > 60
    if stale or _storage_cache["bytes"] > STORAGE_CAP_BYTES:
        total = 0
        for dirpath, _, filenames in os.walk(COLLECTED_DIR):
            for name in filenames:
                try:
                    total += os.path.getsize(os.path.join(dirpath, name))
                except OSError:
                    continue
        _storage_cache.update(ts=now, bytes=total)
    return _storage_cache["bytes"]


def run_core(input_path, work_dir, mode):
    """Run process_document with a concurrency cap and a hard timeout."""
    if not CORE_SLOTS.acquire(timeout=CORE_QUEUE_WAIT_SECONDS):
        raise CoreBusy()
    try:
        future = CORE_POOL.submit(process_document, input_path, work_dir, mode)
        try:
            return future.result(timeout=CORE_TIMEOUT_SECONDS)
        except FuturesTimeoutError:
            future.cancel()
            raise CoreTimeout() from None
    finally:
        CORE_SLOTS.release()


def check_quota(user, premium):
    """Pre-check before processing. Returns error_message or None."""
    if user["unlimited"]:
        return None  # quota re-verified atomically at charge time
    if premium and user["premium_balance"] > 0:
        return None
    if user["balance"] > 0:
        return None
    return "次数已用完，请兑换新卡"


def charge_user(user, premium):
    """Deduct one use after successful processing. Returns error or None."""
    if user["unlimited"]:
        return None if db.charge_unlimited(user["id"]) else "本月无限卡次数已用完（30 次/月）"
    if premium and user["premium_balance"] > 0:
        return None if db.charge_premium(user["id"]) else "次数已用完，请兑换新卡"
    return None if db.charge_balance(user["id"]) else "次数已用完，请兑换新卡"


# ---------------------------------------------------------------- user pages

@app.route("/")
def index():
    user = auth.current_user()
    result = session.pop("result", None)
    return render_template("index.html", user=user, result=result)


@app.route("/register", methods=["GET", "POST"])
def register():
    ip = request.remote_addr or "?"
    if request.method == "POST":
        if auth.too_many_failures(ip):
            flash("尝试过于频繁，请 15 分钟后再试", "error")
        else:
            user_id, error = auth.register_user(
                request.form.get("email", ""), request.form.get("password", "")
            )
            if error:
                auth.record_failure(ip)
                flash(error, "error")
            else:
                session["user_id"] = user_id
                flash("注册成功，已自动登录", "ok")
                return redirect(url_for("index"))
    return render_template("register.html")


@app.route("/login", methods=["GET", "POST"])
def login():
    ip = request.remote_addr or "?"
    if request.method == "POST":
        if auth.too_many_failures(ip):
            flash("尝试过于频繁，请 15 分钟后再试", "error")
        else:
            user, error = auth.login_user(
                request.form.get("email", ""), request.form.get("password", "")
            )
            if error:
                auth.record_failure(ip)
                flash(error, "error")
            else:
                auth.clear_failures(ip)
                session["user_id"] = user["id"]
                target = request.args.get("next")
                if target and target.startswith("/") and not target.startswith("//"):
                    return redirect(target)
                return redirect(url_for("index"))
    return render_template("login.html")


@app.route("/logout")
def logout():
    session.clear()
    flash("已退出登录", "ok")
    return redirect(url_for("index"))


@app.route("/forgot", methods=["GET", "POST"])
def forgot():
    reset_link = None
    ip = request.remote_addr or "?"
    if request.method == "POST":
        if auth.too_many_failures(ip):
            flash("尝试过于频繁，请 15 分钟后再试", "error")
        else:
            token, error = auth.create_reset_token(request.form.get("email", ""))
            if error:
                auth.record_failure(ip)  # also throttles email enumeration
                flash(error, "error")
            else:
                # No mail service by design: the link is shown on the page.
                reset_link = request.host_url.rstrip("/") + url_for("reset", token=[[REDACTED:ACCESS_TOKEN]]
    return render_template("forgot.html", reset_link=reset_link)


@app.route("/reset/<token>", methods=["GET", "POST"])
def reset(token):
    if request.method == "POST":
        error = auth.consume_reset_token(token, request.form.get("password", ""))
        if error:
            flash(error, "error")
        else:
            flash("密码已重置，请使用新密码登录", "ok")
            return redirect(url_for("login"))
    return render_template("reset_password.html", token=[[REDACTED:ACCESS_TOKEN]]


@app.route("/redeem", methods=["POST"])
@auth.login_required
def redeem():
    ok, message = db.redeem_code(session["user_id"], request.form.get("code", ""))
    flash(message, "ok" if ok else "error")
    return redirect(url_for("index"))


# ---------------------------------------------------------------- purchase

@app.route("/buy", methods=["GET", "POST"])
@auth.login_required
def buy():
    db.expire_stale_orders()
    if request.method == "POST":
        order, error = db.create_order(session["user_id"], request.form.get("card_type", ""))
        if error:
            flash(error, "error")
        else:
            return redirect(url_for("pay", order_id=order["id"]))
    return render_template(
        "buy.html",
        products=db.PRODUCTS,
        card_types=db.CARD_TYPES,
        my_orders=db.user_orders(session["user_id"]),
        page_pay_on=PAGE_PAY_ENABLED,
    )


def _load_own_order(order_id):
    """Fetch an order if it belongs to the session user (admin sees all)."""
    order = db.get_order(order_id)
    if not order or (
        order["user_id"] != session.get("user_id") and not session.get("is_admin")
    ):
        return None
    return order


@app.route("/pay/<order_id>")
@auth.login_required
def pay(order_id):
    db.expire_stale_orders()
    order = _load_own_order(order_id)
    if not order:
        abort(404)
    qr_path = os.path.join(app.static_folder, "pay", "alipay_qr.png")
    transfer_link = ""
    if TRANSFER_USER_ID:
        transfer_link = alipay.build_transfer_link(
            TRANSFER_USER_ID, db.yuan(order["amount_cents"]), order["id"]
        )
    return render_template(
        "pay.html",
        order=order,
        card_types=db.CARD_TYPES,
        page_pay_on=PAGE_PAY_ENABLED,
        manual_qr=os.path.isfile(qr_path),
        transfer_uid=TRANSFER_USER_ID,
        transfer_link=transfer_link,
    )


@app.route("/pay/<order_id>/qr.png")
@auth.login_required
def pay_qr(order_id):
    """Dynamic Alipay QR for a pending order, cached on the order row.

    Falls back to the static personal QR when the gateway is unreachable
    or unconfigured, so the pay page never shows a broken image.
    """
    order = _load_own_order(order_id)
    if not order or order["status"] != "pending":
        abort(404)
    import io

    import qrcode

    qr_code = order["qr_code"]
    if not qr_code:
        notify_url = os.environ.get("ALIPAY_NOTIFY_URL") or (
            request.host_url.rstrip("/") + url_for("alipay_notify")
        )
        qr_code, error = alipay.precreate(
            f"DocKit {db.CARD_TYPES[order['card_type']]}",
            order["id"],
            db.yuan(order["amount_cents"]),
            notify_url,
        )
        if not qr_code:
            app.logger.warning("precreate failed for %s: %s", order["id"], error)
            static_qr = os.path.join(app.static_folder, "pay", "alipay_qr.png")
            if os.path.isfile(static_qr):
                return redirect(url_for("static", filename="pay/alipay_qr.png"))
            abort(404)
        from contextlib import closing
        with closing(db.connect()) as conn:
            conn.execute(
                "UPDATE orders SET qr_code = ? WHERE id = ?", (qr_code, order["id"])
            )
            conn.commit()
    buf = io.BytesIO()
    qrcode.make(qr_code, box_size=8, border=2).save(buf, "PNG")
    buf.seek(0)
    return send_file(buf, mimetype="image/png", max_age=0)


@app.route("/pay/<order_id>/transfer_qr.png")
@auth.login_required
def pay_transfer_qr(order_id):
    """QR encoding the prefilled personal-transfer deep link for an order."""
    if not TRANSFER_USER_ID:
        abort(404)
    order = _load_own_order(order_id)
    if not order or order["status"] != "pending":
        abort(404)
    import io

    import qrcode

    link = alipay.build_transfer_link(
        TRANSFER_USER_ID, db.yuan(order["amount_cents"]), order["id"]
    )
    buf = io.BytesIO()
    qrcode.make(link, box_size=8, border=2).save(buf, "PNG")
    buf.seek(0)
    return send_file(buf, mimetype="image/png", max_age=0)


@app.route("/pay/<order_id>/gopay")
@auth.login_required
def pay_gopay(order_id):
    """Redirect the customer's browser to Alipay's hosted payment page."""
    if not PAGE_PAY_ENABLED:
        return redirect(url_for("pay", order_id=order_id))
    db.expire_stale_orders()
    order = _load_own_order(order_id)
    if not order:
        abort(404)
    if order["status"] != "pending":
        return redirect(url_for("pay", order_id=order_id))
    base = request.host_url.rstrip("/")
    pay_url = alipay.build_page_pay_url(
        out_trade_no=order["id"],
        total_amount=db.yuan(order["amount_cents"]),
        subject=f"DocKit {db.CARD_TYPES[order['card_type']]}",
        notify_url=os.environ.get("ALIPAY_NOTIFY_URL") or base + "/pay/alipay/notify",
        return_url=base + url_for("pay_return", order_id=order["id"]),
    )
    return redirect(pay_url)


@app.route("/pay/<order_id>/return", methods=["GET"])
def pay_return(order_id):
    """Alipay redirects the payer back here after payment."""
    order = db.get_order(order_id)
    if not order:
        abort(404)
    # Best-effort verification of the return GET; the async notify at
    # /pay/alipay/notify remains the authoritative confirmation.
    ok, info = alipay.verify_notify(request.args.to_dict())
    if ok and info.get("trade_status") in alipay.SUCCESS_CODES \
            and info.get("out_trade_no") == order_id \
            and info.get("total_amount") == db.yuan(order["amount_cents"]):
        if db.set_order_status(order_id, "paid"):
            db.apply_card_to_user(order["user_id"], order["card_type"])
    return redirect(url_for("pay", order_id=order_id))


@app.route("/pay/<order_id>/cancel", methods=["POST"])
@auth.login_required
def pay_cancel(order_id):
    if db.cancel_order(order_id, session["user_id"]):
        flash("订单已取消", "ok")
    else:
        flash("订单不存在或状态已变化", "error")
    return redirect(url_for("buy"))


@app.route("/pay/alipay/notify", methods=["POST"])
def alipay_notify():
    """Async payment notification from Alipay servers (no session)."""
    ok, info = alipay.verify_notify(request.form.to_dict())
    if not ok:
        app.logger.warning(
            "alipay notify rejected: %s (expected app_id=%r, got %r)",
            info, os.environ.get("ALIPAY_APP_ID"), request.form.get("app_id"),
        )
        return "fail"
    if info["trade_status"] not in alipay.SUCCESS_CODES:
        return "success"  # e.g. user opened but not paid; wait for final state
    order = db.get_order(info["out_trade_no"] or "")
    if not order:
        return "success"
    if info["total_amount"] != db.yuan(order["amount_cents"]):
        app.logger.warning("alipay notify amount mismatch: %s", info)
        return "fail"
    # Idempotent: only the first transition from pending credits the user.
    if db.set_order_status(order["id"], "paid"):
        db.apply_card_to_user(order["user_id"], order["card_type"])
    return "success"


@app.route("/pay/auto/notify", methods=["POST"])
def pay_auto_notify():
    """Manual-mode auto-confirm, called by a phone notification forwarder.

    The phone (MacroDroid or similar) POSTs the raw Alipay arrival
    notification text here with the shared secret from PAY_LISTEN_SECRET.
    Every amount found in the text is matched against pending orders —
    order amounts carry unique cent markers, so a match is unambiguous.
    """
    secret = os.environ.get("PAY_LISTEN_SECRET", "")
    if not secret or not hmac.compare_digest(
        secret, request.form.get("secret", "")
    ):
        abort(403)
    text = request.form.get("text", "")
    amounts = re.findall(r"\d+\.\d{2}", text)
    for amount in amounts:
        cents = int(round(float(amount) * 100))
        order = db.find_pending_order_by_cents(cents)
        if order and db.set_order_status(order["id"], "paid"):
            db.apply_card_to_user(order["user_id"], order["card_type"])
            app.logger.info("auto-confirmed order %s via listener", order["id"])
            return "ok"
    return "no-match"


# ---------------------------------------------------------------- processing

@app.route("/process", methods=["POST"])
@auth.login_required
def process():
    user = auth.current_user()
    premium = request.form.get("premium") == "on"
    original, error = validate_upload(request.files.get("file"))
    if error:
        flash(error, "error")
        return redirect(url_for("index"))

    error = check_quota(user, premium)
    if error:
        flash(error, "error")
        return redirect(url_for("index"))
    if storage_usage() > STORAGE_CAP_BYTES:
        flash("服务器存储空间不足，请稍后再试或联系管理员", "error")
        return redirect(url_for("index"))

    mode = "premium" if premium else "normal"
    work_dir = os.path.join(COLLECTED_DIR, str(user["id"]), ts_dir_name())
    os.makedirs(work_dir, exist_ok=True)
    input_path = os.path.join(work_dir, f"original{file_extension(original)}")
    request.files["file"].save(input_path)

    try:
        output_file, payload_text = run_core(input_path, work_dir, mode)
    except CoreBusy:
        flash("当前处理任务较多，请稍后再试（未扣次数）", "error")
        return redirect(url_for("index"))
    except CoreTimeout:
        flash("文件处理超时，请拆分或缩小文件后重试（未扣次数）", "error")
        return redirect(url_for("index"))
    except ValueError:
        flash("不支持的文件类型", "error")
        return redirect(url_for("index"))
    except Exception:
        app.logger.exception("processing failed for user %s", user["id"])
        flash("文件处理失败，请检查文件是否损坏后重试（未扣次数）", "error")
        return redirect(url_for("index"))

    # Charge only after the core produced its output.
    error = charge_user(user, premium)
    if error:
        flash(error, "error")
        return redirect(url_for("index"))

    db.log_usage(user["id"], original, mode, premium)
    session["result"] = {
        "url": url_for("download", user_id=user["id"], ts=os.path.basename(work_dir),
                        name=os.path.basename(output_file)),
        "name": os.path.basename(output_file),
        "chars": len(payload_text),
    }
    return redirect(url_for("index"))


@app.route("/download/<int:user_id>/<ts>/<name>")
@auth.login_required
def download(user_id, ts, name):
    if session.get("user_id") != user_id and not session.get("is_admin"):
        abort(403)
    if not re.match(r"^[A-Za-z0-9_.-]+$", ts) or not re.match(
        r"^(original|output_[a-z]+)\.[a-z0-9]+$", name
    ):
        abort(404)
    user_dir = os.path.join(COLLECTED_DIR, str(user_id), ts)
    if not os.path.isdir(user_dir):
        abort(404)
    return send_from_directory(user_dir, name, as_attachment=True)


